// CountIDs returns the count of ids with FGA batch filtering applied
func (irq *IntegrationRunQuery) CountIDs(ctx context.Context) (int, error) {
	logx.FromContext(ctx).Debug().Str("query_type", "IntegrationRun").Str("operation", "count_ids").Msg("CountIDs: starting")

	ctx = setContextOp(ctx, irq.ctx, ent.OpQueryIDs)

	ids, err := irq.IDs(ctx)
	if err != nil {
		logx.FromContext(ctx).Error().Err(err).Str("query_type", "IntegrationRun").Str("operation", "count_ids").Msg("CountIDs: IDs() failed")

		return 0, err
	}

	logx.FromContext(ctx).Debug().Str("query_type", "IntegrationRun").Str("operation", "count_ids").Int("count", len(ids)).Msg("CountIDs: completed")

	return len(ids), nil
}

